#include <zlib.h>
#include <vector>
#include <string>
#include <fstream>
#include <iostream>
#include <cstdint>
#include <cmath>
#include <stdexcept>
#include <chrono>
#include <cstring>
struct Scan { gzFile f;std::vector<char>b;size_t pos=0,n=0; Scan(gzFile f):f(f),b(8*1024*1024){} int get(){if(pos==n){int q=gzread(f,b.data(),b.size());if(q<0)throw std::runtime_error("gzip read failed");n=q;pos=0;if(!n)return -1;}return (unsigned char)b[pos++];} bool uint64(uint64_t &v){int c;do{c=get();}while(c>=0 && c<=32);if(c<0)return false;v=0;do{if(c<'0'||c>'9')throw std::runtime_error("noninteger coordinate");v=v*10+(c-'0');c=get();}while(c>32);return true;} void skipval(){int c;do{c=get();}while(c>=0&&c<=32);if(c<0)throw std::runtime_error("early EOF value");while(c>32)c=get();} uint64_t val(){char t[80];size_t k=0;int c;do{c=get();}while(c>=0&&c<=32);if(c<0)throw std::runtime_error("early EOF value");while(c>32){if(k>=79)throw std::runtime_error("value token too long");t[k++]=c;c=get();}t[k]=0;char *e;double x=strtod(t,&e);if(*e || !std::isfinite(x)||x<0||std::abs(x-std::round(x))>1e-9)throw std::runtime_error("selected count not nonnegative integer");return (uint64_t)std::llround(x);} };
std::vector<int32_t> readmap(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("map absent");size_t n=f.tellg();if(n%4)throw std::runtime_error("map length");std::vector<int32_t>v(n/4);f.seekg(0);f.read((char*)v.data(),n);return v;}
int main(int argc,char**argv){try{if(argc!=5)throw std::runtime_error("Usage: source.mtx.gz colmap.bin genemap.bin output_prefix");auto cidx=readmap(argv[2]),gidx=readmap(argv[3]);size_t nb=0,ng=0;for(auto i:cidx)if(i>=0)nb=std::max(nb,size_t(i+1));for(auto i:gidx)if(i>=0)ng=std::max(ng,size_t(i+1));std::vector<uint64_t>libs(nb,0),watch(nb*ng,0);gzFile f=gzopen(argv[1],"rb");if(!f)throw std::runtime_error("source gzip unavailable");gzbuffer(f,8*1024*1024);char header[4096];bool got=false;uint64_t nr=0,nc=0,nnz=0;while(gzgets(f,header,sizeof(header))){if(header[0]=='%')continue;if(sscanf(header,"%lu %lu %lu",&nr,&nc,&nnz)!=3)throw std::runtime_error("bad dimensions");got=true;break;}if(!got||nr+1!=gidx.size()||nc+1!=cidx.size())throw std::runtime_error("dimensions/maps mismatch");auto start=std::chrono::steady_clock::now();Scan s(f);uint64_t r,c,read=0,selected_nnz=0,selected_sum=0;for(;read<nnz;++read){if(!s.uint64(r)||!s.uint64(c))throw std::runtime_error("early EOF coordinates");if(!r||r>nr||!c||c>nc)throw std::runtime_error("coordinate out of bounds");int32_t bi=cidx[c];if(bi>=0){auto v=s.val();libs[bi]+=v;selected_sum+=v;++selected_nnz;int32_t gi=gidx[r];if(gi>=0)watch[size_t(gi)*nb+bi]+=v;}else s.skipval();if((read+1)%100000000==0)std::cerr<<"read "<<read+1<<" / "<<nnz<<"\n";}
if(s.uint64(r))throw std::runtime_error("extra entries beyond header");gzclose(f);std::string pre=argv[4];std::ofstream lo(pre+"_library.uint64",std::ios::binary);lo.write((char*)libs.data(),libs.size()*8);lo.close();std::ofstream wo(pre+"_watch.uint64",std::ios::binary);wo.write((char*)watch.data(),watch.size()*8);wo.close();double sec=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();std::ofstream jo(pre+"_scan.json");jo<<"{\"source_genes\":"<<nr<<",\"source_cells\":"<<nc<<",\"source_nnz\":"<<nnz<<",\"entries_read\":"<<read<<",\"selected_B_cells\":"<<nb<<",\"watch_genes\":"<<ng<<",\"selected_B_nonzero_entries\":"<<selected_nnz<<",\"selected_B_count_sum\":"<<selected_sum<<",\"elapsed_seconds\":"<<sec<<",\"selected_counts_nonnegative_integer\":true,\"whole_matrix_materialized\":false}\n";std::cerr<<"complete "<<read<<" entries in "<<sec<<"s; "<<nb<<" B cells\n";return 0;}catch(std::exception&e){std::cerr<<e.what()<<"\n";return 1;}}
